// <auto-generated />
namespace LiveScore.WebApi.Shared.Middlewares
{
    using System;
    using System.Collections.Generic;
    using Fanex.Caching;
    using LiveScore.Soccer.Matches;
    using LiveScore.Soccer;
    using LiveScore.Features.Odds;
    using LiveScore.Soccer.Enumerations;
    using LiveScore.Soccers.Matches.DataAccesses;
    using Microsoft.Extensions.DependencyInjection;
    using LiveScore.Soccer.Matches.DataAccesses;
    using LiveScore.Providers.SportRadar.Services;

    public static class ServiceMiddleware
    {
        public static void AddServices(this IServiceCollection services)
        {
            services.AddSingleton<ICacheService, CacheService>();


            RegisterMatchService(services);
            RegisterOddsService(services);
        }

        private static void RegisterMatchService(IServiceCollection services)
        {
            services.AddScoped<IMatchService, MatchService>();
            services.AddScoped<MatchDataAccess>();
            services.AddScoped<SportRadarMatchDataAccess>();

            services.AddScoped<Func<int, DataProvider, IMatchDataAccess>>(serviceProvider => (sportId, provider) =>
            {
                switch (sportId)
                {
                    case SportConstants.SoccerId when provider == DataProvider.Database:
                        return serviceProvider.GetService<MatchDataAccess>();

                    case SportConstants.SoccerId when provider == DataProvider.ThirdPartyApi:
                        return serviceProvider.GetService<SportRadarMatchDataAccess>();

                    default:
                        throw new KeyNotFoundException("Not found implementation for " + sportId);
                }
            });
        }

        private static void RegisterOddsService(IServiceCollection services)
        {
            services.AddScoped<OddsService, OddsServiceImpl>();
            services.AddScoped<IOddsFetcher, OddsFetcher>();
            services.AddSingleton<Func<DateTime>>(() =>
            {
                return DateTime.Now;
            });
        }
    }
}